  function makeSelect(label,key,values,current,onChange){const wrap=document.createElement('label');wrap.textContent=label;const select=document.createElement('select');select.dataset.key=key;select.innerHTML=values.map(v=>`<option value="${AXM.escapeHTML(v)}" ${v===current?'selected':''}>${AXM.escapeHTML(v)}</option>`).join('');select.addEventListener('change',()=>onChange(select.value));wrap.appendChild(select);return wrap}
  function makeSlider(label,key,spec,value,onChange){const labelEl=document.createElement('label');const row=document.createElement('div');row.className='control-row';const span=document.createElement('span');span.textContent=label;const output=document.createElement('output');output.textContent=Number(value).toFixed(2);row.append(span,output);const input=document.createElement('input');input.type='range';input.min=spec.minimum??0;input.max=spec.maximum??1;input.step=spec.step??.01;input.value=value;input.dataset.key=key;input.addEventListener('input',()=>{output.textContent=Number(input.value).toFixed(2);onChange(Number(input.value))});labelEl.append(row,input);return labelEl}
