      if(spec.type==='number')container.appendChild(makeSlider(label,key,spec,controls[key],value=>{controls[key]=value;onUpdate()}));
      else if(spec.type==='text')container.appendChild(makeText(label,key,spec,controls[key],value=>{controls[key]=value;onUpdate()}));
      else if(spec.type==='enum')container.appendChild(makeSelect(label,key,spec.values||[],controls[key],value=>{controls[key]=value;onUpdate()}));
