      presets.filter(p=>p.parent===mold.id).forEach(p=>map.insertAdjacentHTML('beforeend',`<div class="lineage-node child" style="margin-left:${Math.min(depth+1,9)*18}px"><b>${AXM.escapeHTML(p.name)}</b><span>${AXM.escapeHTML(p.id)} · sparse preset · ${AXM.escapeHTML(p.approval_state)}</span></div>`));
